41	// Percent-based arithmetic (× 110 ÷ 100) rather than a float rate (× 1.1):
42	// it keeps intermediate values integral and avoids binary floating-point
43	// error — 100 * 1.1 is 110.00000000000001, but (100 * 110) / 100 is exact.
44	const FIRST_INSURANCE_PERCENT_OF_BASE = 110;
45	const ADMIN_FEE = 5;
46	
47	const quote = (step: QuoteStep): QuoteResult => {
48	  const basePremium = BASE_PREMIUMS[step.items[0].type];
49	  const premiumAfterFirstInsurance =
50	    (basePremium * FIRST_INSURANCE_PERCENT_OF_BASE) / 100;
51	  return { premium: premiumAfterFirstInsurance + ADMIN_FEE };
52	};
53	
54	export const runScenario = (scenario: Scenario): ScenarioResult => ({
55	  results: scenario.steps.map(quote),
56	});
