const ONE_HUNDRED_PERCENT = 100;
const FIRST_INSURANCE_PERCENT_OF_BASE = 110;
const ADMIN_FEE = 5;

const applyPercent = (amount: number, percent: number): number =>
  (amount * percent) / ONE_HUNDRED_PERCENT;

const quote = (step: QuoteStep): QuoteResult => {
  const basePremium = BASE_PREMIUMS[step.items[0].type];
  const premiumAfterFirstInsurance = applyPercent(
    basePremium,
    FIRST_INSURANCE_PERCENT_OF_BASE,
  );
  return { premium: premiumAfterFirstInsurance + ADMIN_FEE };
};
